package test;

import org.eclipse.jdt.internal.corext.util.Messages;

// Mock classes to satisfy imports for the example
class CallHierarchyMessages {
    public static String CallHierarchyViewPart_callsToMembers_more = "Members calling ''{0}'', ''{1}'', ''{2}'', ... - in {3}";
    public static String CallHierarchyViewPart_callsFromMembers_more = "Calls from ''{0}'', ''{1}'', ''{2}'', ... - in {3}";
    public static String HistoryAction_inputElements_more = "''{0}'', ''{1}'', ''{2}'', ...";
    public static String CallHierarchyViewPart_callsFromMethod = "Calls from ''{0}'' - in {1}";
}

public class NegativeExample {
    private String getShortLabel(Object o) { return o.toString(); }
    private String scopeDescription = "scope";
    private Object[] fInputElements = new Object[] {"a", "b"};

    public String testMethod3() {
        // Should not match if array has different number of arguments (e.g., 2 instead of 4)
        return Messages.format(CallHierarchyMessages.CallHierarchyViewPart_callsFromMethod,
                new String[] { getShortLabel(fInputElements[0]), scopeDescription });
    }
    public String testMethod4() {
        // Should not match if message key is different from the specified ones
        return Messages.format("SomeOtherKey",
                new String[] { "arg0", "arg1", "arg2", "arg3" });
    }
    public String testMethod5() {
        // Should not match if arguments are not String array
        return Messages.format(CallHierarchyMessages.HistoryAction_inputElements_more,
                new Object[] { "a", "b", "c", "d" });
    }
}
